const db = $('DB: Reagendar Cita Atómica').first().json;

const fecha = new Date(db.out_nueva_fecha_inicio).toLocaleString('es-CO', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: 'numeric', minute: '2-digit', hour12: true,
  timeZone: 'America/Bogota'
});

return [{
  json: {
    exito: true,
    codigo: 'REAGENDADA',
    cita_id: db.out_cita_id,
    servicio: db.out_servicio_nombre,
    nueva_fecha: fecha,
    precio_cop: db.out_precio,
    mensaje_para_cliente: `¡Listo, ${db.out_cliente_nombre}! Tu cita para ${db.out_servicio_nombre} quedó reprogramada con éxito para el ${fecha}. ¡Te esperamos en Cra 83 # 09! ✨`
  }
}];

const r = $input.first().json;
const codigo = r.out_codigo || 'ERROR_TECNICO';

return [{
  json: {
    exito: false,
    codigo: codigo,
    mensaje_para_cliente: r.out_mensaje || 'No se pudo reagendar tu cita en este momento.',
    alternativas: r.out_alternativas || null,
    instruccion_agente: codigo === 'HORARIO_OCUPADO'
      ? 'El nuevo horario está ocupado por otra persona. Comunica mensaje_para_cliente ofreciendo las alternativas indicadas.'
      : 'Comunica mensaje_para_cliente con amabilidad.'
  }
}];
